/* the rescue's dune field: a 128 x 128 height map (0-255) taken from a free model of a sand-dune field (desert.obj, the user's), its crests
   the sharp lines between smooth hollows; tiled mirrored over the battlefield, about 1.2 km a tile (8_rescue.js rsDuneP) */
const RS_DUNE_B64 = '';
/* the sand close up: a 512 px cut of the user's photograph of rippled dune sand, laid with hexagonal tiling (each hex cell its own random
   offset, the cells blended at their edges) so no repeat shows; it shades the ground's own colour, the hue stays the ground's */
const RS_SAND_JPG = 'data:image/jpeg;base64,';
function rsSandMat() {
  const tex = new THREE.TextureLoader().load(RS_SAND_JPG); tex.wrapS = tex.wrapT = THREE.RepeatWrapping; tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  const m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.96, metalness: 0, envMapIntensity: 0.3 });
  m.onBeforeCompile = (sh) => {
    sh.uniforms.uSand = { value: tex };
    sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nvarying vec3 vSandW;').replace('#include <worldpos_vertex>', '#include <worldpos_vertex>\nvSandW = (modelMatrix * vec4(transformed, 1.0)).xyz;');
    sh.fragmentShader = sh.fragmentShader.replace('#include <common>', `#include <common>
varying vec3 vSandW; uniform sampler2D uSand;
vec2 sHash(vec2 p) { return fract(sin(vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)))) * 43758.5453); }
vec3 sHex(vec2 st) {   // hexagonal tiling (Mikkelsen 2022): three samples, each from its cell at a random offset, blended by the cell weights
  vec2 dx = dFdx(st), dy = dFdy(st); vec2 sk = mat2(1.0, 0.0, -0.57735027, 1.15470054) * (st * 3.4641016); vec2 base = floor(sk); vec3 t = vec3(fract(sk), 0.0); t.z = 1.0 - t.x - t.y;
  float s = step(0.0, -t.z), s2 = 2.0 * s - 1.0; vec3 w = vec3(-t.z * s2, s - t.y * s2, s - t.x * s2);
  vec2 v1 = base + vec2(s, s), v2 = base + vec2(s, 1.0 - s), v3 = base + vec2(1.0 - s, s);
  vec3 c1 = textureGrad(uSand, st + sHash(v1), dx, dy).rgb, c2 = textureGrad(uSand, st + sHash(v2), dx, dy).rgb, c3 = textureGrad(uSand, st + sHash(v3), dx, dy).rgb;
  w = pow(w, vec3(6.0)); w /= (w.x + w.y + w.z); return c1 * w.x + c2 * w.y + c3 * w.z; }`)
      .replace('#include <map_fragment>', `#include <map_fragment>
  { float cd = length(vSandW - cameraPosition); vec3 avg = vec3(0.871, 0.701, 0.474);
    vec3 n1 = sHex(vSandW.xz / 4.5) / avg, n2 = sHex(vSandW.xz / 17.0 + 0.37) / avg;   // the ripples, a hand's breadth to a few metres; a larger mottle over it
    vec3 k = mix(n1 * mix(vec3(1.0), n2, 0.45), n2, smoothstep(40.0, 160.0, cd)); k = mix(k, vec3(1.0), smoothstep(160.0, 420.0, cd));
    diffuseColor.rgb *= clamp(mix(vec3(1.0), k, 0.85), 0.4, 1.6); }`);
  };
  m.customProgramCacheKey = () => 'rsSand'; return m;
}
